import sys
from pathlib import Path
import math

ROOT = Path(__file__).resolve().parents[2]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from _workflow_common import (
    business_payload,
    first_maximum,
    validate_contract,
    validate_fit_result,
)


def transform(payloads, contract):
    if type(payloads) is not list:
        raise ValueError("payloads must be a list")
    validate_contract(contract, len(payloads))
    if contract["operation"] != "soft_vote":
        raise ValueError("unsupported operation")

    fit_result = business_payload(payloads[0])
    classes, sample_count = validate_fit_result(fit_result)
    class_index = {label: index for index, label in enumerate(classes)}
    probability_terms = [[[] for _ in classes] for _ in range(sample_count)]
    member_weights = []

    for member in fit_result["members"]:
        weight = member["weight"]
        member_weights.append(weight)
        member_index = {label: index for index, label in enumerate(member["classes"])}
        for sample_index, row in enumerate(member["probabilities"]):
            for label, global_index in class_index.items():
                probability_terms[sample_index][global_index].append(
                    weight * row[member_index[label]]
                )

    total_weight = math.fsum(member_weights)
    if total_weight <= 0:
        raise ValueError("total member weight must be positive")
    probabilities = [
        [math.fsum(terms) / total_weight for terms in sample_terms]
        for sample_terms in probability_terms
    ]

    predictions = []
    for row in probabilities:
        best_index = first_maximum(row)
        predictions.append(classes[best_index])

    result = {"predictions": predictions, "probabilities": probabilities}
    return {"name": contract["name"], "result": result}
